export function addUpdates(container){
 const api=window.plystreakDesktop;if(!api)return;
 const box=document.createElement('section');box.className='update-panel';box.innerHTML='<hr><span class="eyebrow">APP PER PC</span><h3>Aggiornamenti</h3><p>Scarica le nuove funzioni da qui e continua a giocare anche offline. Partite e preferenze restano sul dispositivo.</p><p data-status role="status" aria-live="polite">Controlla se è disponibile una nuova versione.</p><p data-notes class="muted"></p><div class="update-actions"><button data-check>Controlla aggiornamenti</button><button data-login hidden>Accedi al sito privato</button><button data-install hidden>Scarica aggiornamento</button><button data-restart hidden>Riavvia e aggiorna</button></div><small>Il controllo richiede Internet. Gli aggiornamenti del programma nativo possono richiedere una nuova installazione.</small>';
 container.append(box);const q=s=>box.querySelector('[data-'+s+']');let busy=false;
 const run=async(action)=>{if(busy)return;busy=true;box.querySelectorAll('button').forEach(b=>b.disabled=true);try{await action()}catch{q('status').textContent='Connessione non disponibile. Puoi continuare a giocare offline e riprovare più tardi.'}finally{busy=false;box.querySelectorAll('button').forEach(b=>b.disabled=false)}};
 const show=r=>{q('login').hidden=r.status!=='login';if(r.status==='login')q('status').textContent='Il sito è privato: accedi nella finestra dedicata, poi premi di nuovo Controlla aggiornamenti.';else if(r.status==='error')q('status').textContent=r.message||'Controllo non riuscito.';return r.status==='error'||r.status==='login'};
 q('check').onclick=()=>run(async()=>{q('install').hidden=true;q('notes').textContent='';q('status').textContent='Cerco aggiornamenti…';const r=await api.check();if(show(r))return;if(r.status==='current')q('status').textContent=`Hai già la versione più recente: ${r.current}.`;if(r.status==='shell')q('status').textContent=`La versione ${r.version} richiede una nuova versione dell’app PC. Scaricala dalla conversazione in cui è stata creata.`;if(r.status==='available'){q('status').textContent=`Disponibile ${r.version} · ${(r.size/1048576).toFixed(1)} MB`;q('notes').textContent=r.notes;q('install').hidden=false}});
 q('login').onclick=()=>run(async()=>{show(await api.login())});
 q('install').onclick=()=>run(async()=>{q('status').textContent='Scarico e verifico l’aggiornamento…';const r=await api.install();if(show(r))return;q('install').hidden=true;q('check').hidden=true;q('restart').hidden=false;q('status').textContent=`Versione ${r.version} pronta. Prima di riavviare, termina o esporta la partita in corso. Puoi riavviare anche chiudendo e riaprendo l’app.`});
 q('restart').onclick=()=>run(async()=>{show(await api.restart())});
}
